}

int overlap_compute(size_t i, void* ctx) {
  int* sum = static_cast<int*>(ctx);
  *sum += static_cast<int>(i + 1);
  return static_cast<int>(i + 1);
}

void overlap_comm(size_t, int value, void* ctx) {
  int* total = static_cast<int*>(ctx);
  *total += value;
}

